{
  "title": "Discussion on tax filing, domain purchase, app profitability, and source‑code access",
  "topics": [
    {
      "id": "tax-filing",
      "title": "Tax filing and avoiding penalties",
      "claims": [
        {
          "text": "Paying 500 UAH to aunt Sveta can help avoid a large amount of penalties by correctly re‑filing declarations.",
          "evidence": [1]
        },
        {
          "text": "The inspector ignored the author's declarations for a year and only later demanded verification of all years.",
          "evidence": [1]
        },
        {
          "text": "The critical part is not the tax calculation itself but correctly matching each column and subtraction.",
          "evidence": [8, 5]
        },
        {
          "text": "The whole re‑filing procedure typically takes about an hour with Excel.",
          "evidence": [5]
        }
      ]
    },
    {
      "id": "domain-purchase",
      "title": "Domain purchase discussion",
      "claims": [
        {
          "text": "No domain has been bought yet.",
          "evidence": [2]
        },
        {
          "text": "Someone suggests buying a calculator first so there will be money for the domain.",
          "evidence": [4]
        },
        {
          "text": "Another participant doubts anyone will buy a domain.",
          "evidence": [9]
        },
        {
          "text": "The domain is considered a “silly thing” that won’t evaporate even in hot weather.",
          "evidence": [10]
        }
      ]
    },
    {
      "id": "app-profitability",
      "title": "Profitability of web vs mobile apps",
      "claims": [
        {
          "text": "Web platforms are the simplest but far less profitable than Android/iOS apps.",
          "evidence": [11]
        },
        {
          "text": "Web SEO is poor; even on the 10th Google page the site is not found.",
          "evidence": [11]
        },
        {
          "text": "There is no external traffic from social platforms or contextual ads, unlike app stores which promote new releases.",
          "evidence": [11]
        },
        {
          "text": "Passive ad revenue on a website is absent and user retention is near zero due to early paywalls.",
          "evidence": [11]
        },
        {
          "text": "Successful side‑projects use very fast delivery (under a week) and cross‑platform stacks like Flutter.",
          "evidence": [12]
        },
        {
          "text": "The author doubts the market will buy the product, estimating low sales.",
          "evidence": [17]
        },
        {
          "text": "LinkedIn audience shows decreasing technical/managerial posts, potentially affecting demand.",
          "evidence": [18]
        }
      ]
    },
    {
      "id": "source-code-piracy",
      "title": "Source code access, passwords and piracy concerns",
      "claims": [
        {
          "text": "The app’s source code is not publicly available; the only password is stored locally as a 100 % discount promo code.",
          "evidence": [20, 21]
        },
        {
          "text": "The author jokes about finding the password via search, implying possible easy cracking.",
          "evidence": [28]
        },
        {
          "text": "Participants accuse each other of piracy, referencing “bundle” price and demand for the password.",
          "evidence": [22, 23, 24, 26, 27, 32, 33, 34]
        },
        {
          "text": "The app is positioned as a “local‑first” tool with occasional USD/UAH rate updates, but the paid bundle contains the actual value.",
          "evidence": [29, 30]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Is there a viable market of at least ten people willing to pay 299 UAH for the app?",
      "evidence": [20]
    }
  ]
}
